import { crypto } from "node:crypto";

export function timingSafeEqual(a: string, b: string): boolean {
  const aBytes = new TextEncoder().encode(a);
  const bBytes = new TextEncoder().encode(b);

  // Early return if lengths differ
  if (aBytes.length !== bBytes.length) {
    return false;
  }

  // Use crypto.timingSafeEqual for constant-time comparison
  return crypto.timingSafeEqual(aBytes, bBytes);
}

/**
 * Generate a random delay with jitter for security purposes.
 * This helps prevent timing attacks by adding randomness to the response time.
 *
 * @param minMs Minimum delay in milliseconds
 * @param maxMs Maximum delay in milliseconds
 * @returns Promise that resolves after the random delay
 */
export function addJitter(minMs: number, maxMs: number): Promise<void> {
  const delay = minMs + Math.random() * (maxMs - minMs);
  return new Promise((resolve) => setTimeout(resolve, delay));
}

